    ['-e', 'process.stdout.write(JSON.stringify({agent: process.env.LATTICE_AGENT ?? null, role: process.env.LATTICE_ACTIVITY_ROLE ?? null}))'],
    { env, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] },
  );
  assert.deepEqual(
    JSON.parse(observed),
    { agent: null, role: null },
    `suite child process inherited reviewer dispatch authority: ${observed}`,
  );
}

